    expect(spokenPrefix('your table is booked', 'your table table')).toBe('your table');
  });

  test('counts a repeated phrase, a restarted word and a stuttered letter once', () => {
    expect(spokenPrefix(TICKET, 'I can I can heelp you')).toBe('I can help you');
    expect(spokenPrefix(TICKET, 'I can he help you')).toBe('I can help you');
    expect(spokenPrefix('you can see your bookings here', 'yyou can see your')).toBe('you can see your');
  });

