    expect(spokenPrefix(TICKET, TICKET)).toBe(TICKET);
    expect(spokenPrefix(TICKET, `${TICKET} ticket`)).toBe(TICKET);
  });

  test('shows whole words only, leaving out a word the speech has not finished', () => {
    expect(spokenPrefix(TICKET, 'I can he')).toBe('I can');
    expect(spokenPrefix(TICKET, 'I can help you bo')).toBe('I can help you');
    expect(spokenPrefix(TICKET, 'I can help')).toBe('I can help');
  });

  test('never ends the caption on a space', () => {
    expect(spokenPrefix(TICKET, 'I can ')).toBe('I can');
    expect(spokenPrefix('let me check that for you', 'let me ')).toBe('let me');
  });

  test('takes the longer reading when a repeat could also be the next words', () => {
    expect(spokenPrefix('bye bye for now', 'bye bye')).toBe('bye bye');
  });

  test('counts the letters inside a repeat toward the next word, in order', () => {
    // The second "can" holds an "a" after a space, so by the rule the word "a" counts.
    expect(spokenPrefix('I can a lot', 'I can can')).toBe('I can a');
    // Spaces count as well: with no space after "can", the repeated "a" cannot start the next word.
    expect(spokenPrefix('I can a lot', 'I cana')).toBe('I can');
