    const spoken = words
      .slice(0, 350)
      .map((word, i) => (i % 11 === 0 ? word[0] + word : word) + (i % 5 === 0 ? ` ${word}` : ''))
      .join(' ');
    expect(spokenPrefix(intended, spoken)).toBe(words.slice(0, 350).join(' '));
  });
});

