// How much of the intended text the voice agent has said, for the live caption.
// The agent only ever repeats itself, so what it has said of the intended text shows up in the spoken text in order:
// one pass over the spoken text finds how far that reaches, and the caption keeps the whole words up to there.
export default function spokenPrefix(intended, spoken) {
  let said = 0;
  for (let j = 0; j < spoken.length && said < intended.length; j++) {
    if (spoken[j] === intended[said]) said += 1;
  }
  // A word counts once its last letter has been said: the text ends there, or a space comes next.
  if (said === intended.length || intended[said] === ' ') return intended.slice(0, said);
  const lastSpace = intended.lastIndexOf(' ', said - 1);
  return lastSpace < 0 ? '' : intended.slice(0, lastSpace);
}

