// @file src/ids.js
let sequence = 0;

/** A new id on every call, such as "page_3". */
export function createId(prefix) {
  sequence += 1;
  return `${prefix}_${sequence}`;
}

// @file src/pages.js
import { createId } from './ids.js';

/**
 * The app's pages. A page is { id, title, blocks, createdAt, updatedAt } and a block is { id, text, version }.
 * now() returns the time in milliseconds; the tests pass a clock they move by hand. Every change is reported to the
 * listeners added with onChange, as { type: 'create' | 'update', pageId }.
 */
export function createPages({ now }) {
  const pages = new Map();
  const listeners = [];
  const notify = (change) => listeners.forEach((listener) => listener(change));

  return {
    createPage(title) {
      const time = now();
      const page = { id: createId('page'), title, blocks: [], createdAt: time, updatedAt: time };
      pages.set(page.id, page);
      notify({ type: 'create', pageId: page.id });
      return page;
    },
    addBlock(pageId, text) {
      const page = pages.get(pageId);
      const block = { id: createId('block'), text, version: 1 };
      page.blocks.push(block);
      page.updatedAt = now();
      notify({ type: 'update', pageId });
      return block;
    },
    updateBlock(pageId, blockId, text) {
      const page = pages.get(pageId);
      const index = page.blocks.findIndex((block) => block.id === blockId);
      // A changed block is a new object with a higher version, so a renderer can tell it from the old one.
      page.blocks[index] = { ...page.blocks[index], text, version: page.blocks[index].version + 1 };
      notify({ type: 'update', pageId });
    },
    getPage(pageId) {
      return pages.get(pageId);
    },
    /** The pages changed most recently first, at most `limit` of them. */
    recentPages(limit) {
      return [...pages.values()].sort((a, b) => b.updatedAt - a.updatedAt).slice(0, limit);
    },
    onChange(listener) {
      listeners.push(listener);
    },
  };
}

// @file src/search.js
/**
 * A word index over each page's title and block texts, kept up to date as pages change. search(query) returns the
 * ids of the pages that contain every word of the query, ignoring case, in the order the pages were created.
 * Create it before adding pages: it learns about pages from their change events.
 */
export function createSearch(pages) {
  const wordsByPage = new Map();
  const wordsOf = (text) => text.toLowerCase().split(/\W+/).filter(Boolean);

  const index = (pageId) => {
    const page = pages.getPage(pageId);
    wordsByPage.set(pageId, new Set(wordsOf([page.title, ...page.blocks.map((block) => block.text)].join(' '))));
  };

  pages.onChange(({ type, pageId }) => {
    if (type === 'create') index(pageId);
  });

  return {
    search(query) {
      const words = wordsOf(query);
      if (words.length === 0) return [];
      return [...wordsByPage.keys()].filter((pageId) => words.every((word) => wordsByPage.get(pageId).has(word)));
    },
  };
}

// @file src/titles.js
/**
 * The title the sidebar shows: runs of white space become one space and the ends are trimmed, an empty title reads
 * "Untitled", and a title longer than maxLength is cut at a word boundary and ends with "…". A cut title, ellipsis
 * included, is never longer than maxLength.
 */
export function displayTitle(title, maxLength = 24) {
  var result;
  var words = String(title).split(/\s+/);
  var cleaned = [];
  for (var i = 0; i < words.length; i++) {
    if (words[i] !== '') {
      cleaned.push(words[i]);
    }
  }
  if (cleaned.length == 0) {
    result = 'Untitled';
  } else {
    var joined = cleaned.join(' ');
    if (joined.length < maxLength) {
      result = joined;
    } else {
      var cut = '';
      for (var j = 0; j < cleaned.length; j++) {
        var next = cut === '' ? cleaned[j] : cut + ' ' + cleaned[j];
        if (next.length > maxLength - 1) {
          break;
        }
        cut = next;
      }
      if (cut === '') {
        cut = joined.slice(0, maxLength - 1);
      }
      result = cut + '…';
    }
  }
  return result;
}

// @file src/render.js
/**
 * Turns a page's blocks into rows with renderBlock(block), which is the slow part. A row is reused until its block
 * changes; a changed block has a higher version.
 */
export function createRenderer(renderBlock) {
  const rows = new Map();

  return {
    renderPage(page) {
      return page.blocks.map((block) => {
        const cached = rows.get(block);
        if (cached && cached.version === block.version) return cached.row;
        const row = renderBlock(block);
        rows.set(block.id, { version: block.version, row });
        return row;
      });
    },
  };
}

