// A clock the test moves by hand, one millisecond at a time.
const manualClock = () => {
  let time = 0;
  return {
    now: () => time,
    tick: () => {
      time += 1;
    },
  };
};

describe('pages', () => {
  test('lists recent pages newest first, up to the limit', () => {
    const clock = manualClock();
    const pages = createPages({ now: clock.now });
    pages.createPage('Roadmap');
    clock.tick();
    pages.createPage('Meeting notes');
    clock.tick();
    pages.createPage('Ideas');
    expect(pages.recentPages(2).map((page) => page.title)).toEqual(['Ideas', 'Meeting notes']);
    expect(pages.recentPages(5).map((page) => page.title)).toEqual(['Ideas', 'Meeting notes', 'Roadmap']);
  });

  test('an edit moves its page to the top of the recent list', () => {
    const clock = manualClock();
    const pages = createPages({ now: clock.now });
    const roadmap = pages.createPage('Roadmap');
    clock.tick();
    const goals = pages.addBlock(roadmap.id, 'Q1 goals');
    clock.tick();
    pages.createPage('Meeting notes');
    clock.tick();
    pages.updateBlock(roadmap.id, goals.id, 'Q1 and Q2 goals');
    expect(pages.getPage(roadmap.id).blocks[0].text).toBe('Q1 and Q2 goals');
    expect(pages.recentPages(2).map((page) => page.title)).toEqual(['Roadmap', 'Meeting notes']);
  });
});

describe('search', () => {
  test('finds pages by every word of the query, ignoring case', () => {
    const pages = createPages({ now: () => 0 });
    const search = createSearch(pages);
    const roadmap = pages.createPage('Product roadmap');
    const retro = pages.createPage('Sprint retro');
    expect(search.search('ROADMAP')).toEqual([roadmap.id]);
    expect(search.search('sprint retro')).toEqual([retro.id]);
    expect(search.search('roadmap retro')).toEqual([]);
    expect(search.search('  ')).toEqual([]);
  });

  test('finds text added or edited after the page was created', () => {
    const pages = createPages({ now: () => 0 });
    const search = createSearch(pages);
    const roadmap = pages.createPage('Roadmap');
    const launch = pages.addBlock(roadmap.id, 'Launch in March');
    expect(search.search('march')).toEqual([roadmap.id]);
    pages.updateBlock(roadmap.id, launch.id, 'Launch in April');
    expect(search.search('april')).toEqual([roadmap.id]);
    expect(search.search('march')).toEqual([]);
  });
});

